INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0009-0000-0000-000000000017','TCF','22222222-0000-0000-0000-000000000002','44444444-0009-0000-0000-000000000006',NULL,'B2','CE','Quelle est l''idée principale défendue par l''auteur ?','L''auteur conclut explicitement : « Une véritable réforme structurelle, plutôt que des primes ponctuelles, semble aujourd''hui nécessaire ». Il défend donc une réforme de fond. Il ne nie pas le problème (il l''étend même aux périphéries urbaines), juge les primes insuffisantes, et n''affirme pas que les jeunes médecins refusent d''exercer en France (seulement qu''ils refusent les zones isolées).','true','2026-05-27 17:40:30.147221+02','2026-05-27 17:40:30.147221+02','ACTIVE',NULL,NULL,'ce_idee_principale');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0009-0000-0000-000000000018','TCF','22222222-0000-0000-0000-000000000002','44444444-0009-0000-0000-000000000006',NULL,'B2','CE','Que peut-on déduire du comportement des jeunes médecins selon le texte ?','Le texte dit qu''ils « plébiscitent l''exercice en cabinet de groupe et refusent souvent les zones isolées ». On en déduit qu''ils préfèrent travailler à plusieurs et dans des zones plus peuplées. Le texte ne dit pas qu''ils acceptent les zones isolées (même avec des primes), ni qu''ils quittent la profession, ni qu''ils privilégient les hôpitaux publics.','true','2026-05-27 17:40:30.147221+02','2026-05-27 17:40:30.147221+02','ACTIVE',NULL,NULL,'ce_inference_intention');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0009-0000-0000-000000000019','TCF','22222222-0000-0000-0000-000000000002','44444444-0009-0000-0000-000000000007',NULL,'B2','CE','Selon le texte, à quoi est attribué le recul des ventes de voitures électriques ?','Le texte énumère trois causes : « suppression progressive des aides à l''achat, hausse du prix de l''électricité, mais aussi inquiétudes des automobilistes quant à l''autonomie réelle ». Le texte ne mentionne ni interdiction gouvernementale, ni absence de modèles disponibles, ni rejet de l''écologie.','true','2026-05-27 17:40:30.147221+02','2026-05-27 17:40:30.147221+02','ACTIVE',NULL,NULL,'ce_reformulation');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0009-0000-0000-000000000020','TCF','22222222-0000-0000-0000-000000000002','44444444-0009-0000-0000-000000000008',NULL,'B2','CE','Quelle est la position de l''auteur sur le succès des plateformes de streaming ?','L''auteur reconnaît les avantages (« certes, elles ont démocratisé l''accès… », « productions locales… ») puis introduit ses réserves (« mais on aurait tort d''en conclure que tout est positif »). Sa conclusion interrogative (« ne risque-t-on pas… ») renforce la prudence. Sa position est donc nuancée et critique, ni totalement favorable, ni hostile au point d''appeler à interdire, ni neutre.','true','2026-05-27 17:40:30.147221+02','2026-05-27 17:40:30.147221+02','ACTIVE',NULL,NULL,'ce_ton_auteur');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0010-0000-0000-000000000017','TCF','22222222-0000-0000-0000-000000000002','44444444-0010-0000-0000-000000000005',NULL,'B2','CE','Quelle est l''idée principale de cette tribune ?','L''auteur conclut : « La question n''est sans doute plus de savoir si le télétravail doit perdurer, mais à quelles conditions il peut bénéficier à toutes les parties ». Il défend donc l''idée que le télétravail doit être encadré ou aménagé. Il ne le condamne pas, ne le glorifie pas, et ne se contente pas de rapporter ce que font les entreprises.','true','2026-05-27 17:40:30.164849+02','2026-05-27 17:40:30.164849+02','ACTIVE',NULL,NULL,'ce_idee_principale');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0010-0000-0000-000000000018','TCF','22222222-0000-0000-0000-000000000002','44444444-0010-0000-0000-000000000005',NULL,'B2','CE','Que reprochent les responsables d''équipe au télétravail, selon le texte ?','Le texte indique que les responsables « s''inquiètent d''une perte progressive de la culture commune et d''une difficulté à intégrer les nouveaux arrivants ». Leurs préoccupations sont donc collectives (cohésion, intégration), pas individuelles. Le texte ne dit ni qu''ils craignent une baisse de productivité, ni qu''ils dénoncent les abus, ni qu''ils s''opposent à un retour au bureau.','true','2026-05-27 17:40:30.164849+02','2026-05-27 17:40:30.164849+02','ACTIVE',NULL,NULL,'ce_inference_intention');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0010-0000-0000-000000000019','TCF','22222222-0000-0000-0000-000000000002','44444444-0010-0000-0000-000000000006',NULL,'B2','CE','Selon le texte, à quoi est lié le succès des produits ultra-transformés ?','Le texte précise : « Pourtant, ces produits restent attractifs : peu chers, prêts à consommer, et massivement présents dans les linéaires ». Le succès s''explique donc par leur prix, leur côté pratique et leur disponibilité. Le texte n''évoque pas leurs qualités nutritionnelles (au contraire), ni la publicité ou la mode comme cause explicite.','true','2026-05-27 17:40:30.164849+02','2026-05-27 17:40:30.164849+02','ACTIVE',NULL,NULL,'ce_reformulation');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0010-0000-0000-000000000020','TCF','22222222-0000-0000-0000-000000000002','44444444-0010-0000-0000-000000000006',NULL,'B2','CE','Quelle position adopte l''auteur sur les politiques publiques à mener ?','L''auteur écrit : « Sans une politique publique ambitieuse, qui pourrait inclure une taxation différenciée ou un étiquetage plus explicite, il est difficile de croire que les habitudes changeront d''elles-mêmes ». Il appelle donc à une action publique forte, en avançant des pistes concrètes. Il ne prône pas le laisser-faire, ne se contente pas de constater, et n''accuse pas directement les consommateurs.','true','2026-05-27 17:40:30.164849+02','2026-05-27 17:40:30.164849+02','ACTIVE',NULL,NULL,'ce_ton_auteur');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0011-0000-0000-000000000017','TCF','22222222-0000-0000-0000-000000000002','44444444-0011-0000-0000-000000000005',NULL,'B2','CE','Quelle idée principale défend l''auteur de ce texte ?','L''auteur conclut : « Tant qu''elle [la transparence salariale] ne se généralisera pas, il sera difficile d''espérer un véritable rattrapage. » Il défend donc l''idée que la transparence salariale est une condition nécessaire pour faire reculer les inégalités. Il ne nie pas le problème (il le documente), ne le réduit pas aux choix individuels, et ne dit pas que les écarts ont disparu.','true','2026-05-27 17:40:30.178875+02','2026-05-27 17:40:30.178875+02','ACTIVE',NULL,NULL,'ce_idee_principale');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0011-0000-0000-000000000018','TCF','22222222-0000-0000-0000-000000000002','44444444-0011-0000-0000-000000000005',NULL,'B2','CE','Selon le texte, à quoi sont attribuées les inégalités salariales ?','Le texte énumère plusieurs causes : « autocensure dans la négociation, accès plus difficile aux postes à responsabilité, ou encore prise en charge majoritaire des contraintes familiales ». Les causes sont donc multiples. Le texte ne dit pas que tout vient d''une discrimination volontaire des employeurs, ni que les femmes sont moins compétentes, ni qu''il s''agit d''un manque de qualification.','true','2026-05-27 17:40:30.178875+02','2026-05-27 17:40:30.178875+02','ACTIVE',NULL,NULL,'ce_reformulation');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0011-0000-0000-000000000019','TCF','22222222-0000-0000-0000-000000000002','44444444-0011-0000-0000-000000000006',NULL,'B2','CE','Pourquoi les fausses informations circulent-elles plus vite, selon le texte ?','Le texte dit explicitement : « en grande partie parce qu''elle suscite des réactions émotionnelles plus fortes ». L''explication tient donc à la dimension émotionnelle. Le texte ne dit ni que les modérateurs les favorisent, ni que les utilisateurs ne savent pas lire, ni que les vraies informations sont volontairement bloquées.','true','2026-05-27 17:40:30.178875+02','2026-05-27 17:40:30.178875+02','ACTIVE',NULL,NULL,'ce_detail_specifique');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0011-0000-0000-000000000020','TCF','22222222-0000-0000-0000-000000000002','44444444-0011-0000-0000-000000000006',NULL,'B2','CE','Quelle solution l''auteur juge-t-il la plus efficace à long terme ?','Le texte conclut : « Renforcer l''éducation aux médias dès le plus jeune âge apparaît [...] comme une réponse plus durable que toute solution purement technique. » La priorité défendue est donc l''éducation aux médias. Les outils de modération sont jugés insuffisants (ils interviennent trop tard). L''interdiction des réseaux et la régulation pénale ne sont pas évoquées.','true','2026-05-27 17:40:30.178875+02','2026-05-27 17:40:30.178875+02','ACTIVE',NULL,NULL,'ce_ton_auteur');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0012-0000-0000-000000000017','TCF','22222222-0000-0000-0000-000000000002','44444444-0012-0000-0000-000000000005',NULL,'B2','CE','Quelle position adopte l''auteur sur le numérique à l''école ?','L''auteur conclut : « Plutôt qu''un débat caricatural pour ou contre, sans doute faudrait-il s''interroger sur les conditions concrètes d''une intégration réfléchie ». Il refuse donc le débat binaire et défend une approche pragmatique, attentive aux conditions d''usage. Il ne défend ni l''adoption massive, ni l''interdiction, ni l''idée que les études ont déjà tranché.','true','2026-05-27 17:40:30.194289+02','2026-05-27 17:40:30.194289+02','ACTIVE',NULL,NULL,'ce_ton_auteur');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0012-0000-0000-000000000018','TCF','22222222-0000-0000-0000-000000000002','44444444-0012-0000-0000-000000000005',NULL,'B2','CE','Quels inconvénients du numérique le texte évoque-t-il ?','Le texte cite trois inquiétudes : « une baisse de la concentration, un appauvrissement de l''écriture manuscrite et une dépendance précoce aux écrans ». Le texte n''évoque ni l''absence d''équipement, ni un coût financier excessif, ni un problème de formation des enseignants comme tel.','true','2026-05-27 17:40:30.194289+02','2026-05-27 17:40:30.194289+02','ACTIVE',NULL,NULL,'ce_reformulation');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0012-0000-0000-000000000019','TCF','22222222-0000-0000-0000-000000000002','44444444-0012-0000-0000-000000000006',NULL,'B2','CE','Quelle est l''idée principale développée dans ce texte ?','Le texte décrit les nouvelles politiques de mobilité urbaine, leur accueil globalement favorable, mais aussi les réserves de certaines catégories. Sa conclusion appelle les municipalités à « montrer, chiffres à l''appui, que ces craintes ne se vérifient pas toujours, et à accompagner les usagers les plus fragiles ». Le texte décrit donc une transformation en cours qui suscite des tensions à résoudre. Il ne dit ni qu''il y a un consensus, ni que les politiques échouent, ni que la voiture reste indispensable.','true','2026-05-27 17:40:30.194289+02','2026-05-27 17:40:30.194289+02','ACTIVE',NULL,NULL,'ce_idee_principale');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0012-0000-0000-000000000020','TCF','22222222-0000-0000-0000-000000000002','44444444-0012-0000-0000-000000000006',NULL,'B2','CE','Que craignent les commerçants face à ces nouvelles mesures ?','Le texte dit : « Les premiers [les commerçants] redoutent une baisse de leur clientèle ». Leur crainte porte donc sur leur activité économique. Le texte n''évoque ni la hausse de leurs charges, ni une concurrence en ligne, ni des problèmes de livraison.','true','2026-05-27 17:40:30.194289+02','2026-05-27 17:40:30.194289+02','ACTIVE',NULL,NULL,'ce_inference_intention');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0013-0000-0000-000000000009','TCF','22222222-0000-0000-0000-000000000002','44444444-0013-0000-0000-000000000001',NULL,'B2','CE','Quelle est l''idée principale défendue par l''auteur ?','L''auteur écrit explicitement : « Le constat mérite d''être nuancé. Les enquêtes récentes montrent en réalité qu''elles ne refusent pas le travail, mais qu''elles cherchent davantage à lui donner du sens ». Il défend donc l''idée que les jeunes ne sont pas paresseux mais réclament du sens. Il ne valide pas le cliché de paresse, ne dit pas que les entreprises refusent ces aspirations (au contraire, certaines s''adaptent), et ne juge pas non plus le modèle traditionnel meilleur.','true','2026-05-27 17:40:30.209527+02','2026-05-27 17:40:30.209527+02','ACTIVE',NULL,NULL,'ce_idee_principale');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0013-0000-0000-000000000010','TCF','22222222-0000-0000-0000-000000000002','44444444-0013-0000-0000-000000000001',NULL,'B2','CE','Que recherchent concrètement les jeunes actifs, selon le texte ?','Le texte énumère trois attentes : « conditions plus respectueuses, équilibre avec la vie personnelle, missions qui les engagent réellement ». Le texte ne cite ni un salaire élevé, ni des promotions rapides, ni un télétravail intégral comme priorités.','true','2026-05-27 17:40:30.209527+02','2026-05-27 17:40:30.209527+02','ACTIVE',NULL,NULL,'ce_reformulation');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0013-0000-0000-000000000011','TCF','22222222-0000-0000-0000-000000000002','44444444-0013-0000-0000-000000000002',NULL,'B2','CE','Que peut-on conclure du comportement des lecteurs décrit dans le texte ?','Le texte indique que « certains lecteurs combinent même les deux supports, profitant du numérique pour ses bibliothèques infinies, et revenant au papier dès qu''il s''agit d''un texte qu''ils souhaitent vraiment savourer ». La conclusion est donc que papier et numérique se complètent plutôt qu''ils ne s''excluent. Le texte ne dit pas que le numérique a définitivement gagné, que les lecteurs rejettent le numérique, ni que la lecture diminue globalement.','true','2026-05-27 17:40:30.209527+02','2026-05-27 17:40:30.209527+02','ACTIVE',NULL,NULL,'ce_inference_intention');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0013-0000-0000-000000000012','TCF','22222222-0000-0000-0000-000000000002','44444444-0013-0000-0000-000000000002',NULL,'B2','CE','Pour quelles raisons le livre papier garde-t-il une place importante ?','Le texte énumère trois facteurs : « un attachement sensoriel à l''objet, le confort visuel à la lecture longue, et le rôle social que joue encore la bibliothèque personnelle ». Le prix, le rejet du numérique ou un attachement traditionaliste ne sont pas évoqués comme explications.','true','2026-05-27 17:40:30.209527+02','2026-05-27 17:40:30.209527+02','ACTIVE',NULL,NULL,'ce_reformulation');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0020-0000-0000-000000000003','TCF','22222222-0000-0000-0000-000000000002',NULL,'33333333-0020-0000-0000-000000000002','B2','CE','Quelle est la position défendue par l''auteur dans cet article ?','L''auteur reconnaît les bénéfices du télétravail (« plébiscité par les salariés », chiffres positifs) tout en pointant ses limites (troubles musculosquelettiques, isolement des jeunes, perte des savoir-faire informels). Il conclut explicitement : « Plutôt que d''opposer naïvement défenseurs et détracteurs, l''heure est venue de penser un télétravail intelligent : limité dans son volume, accompagné dans ses outils, et surtout pensé en fonction des métiers ». Il défend donc une position d''équilibre, qui appelle à un usage régulé du télétravail. La réponse A confond constat (le télétravail séduit les salariés) et position défendue (l''article ne plaide pas pour son extension). La réponse C est une demi-vérité : l''auteur évoque effectivement des limites mais n''appelle absolument pas à revenir au présentiel. La réponse D adopte une position adjacente mais trop tranchée : l''auteur ne dit pas que le télétravail est un échec, il appelle à l''ajuster.','true','2026-05-27 17:40:30.286561+02','2026-05-27 17:40:30.286561+02','ACTIVE',NULL,NULL,'ce_ton_auteur');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0020-0000-0000-000000000010','TCF','22222222-0000-0000-0000-000000000002',NULL,'33333333-0020-0000-0000-000000000003','B2','CE','Quelle position l''auteur défend-il à propos de l''expression « démission silencieuse » ?','L''auteur écrit explicitement que l''expression « mérite d''être interrogée » et qu''elle est « trompeuse : on ne démissionne pas en restant ». Sa critique porte sur le terme lui-même, qu''elle juge mal nommé, et non sur le phénomène qu''il décrit (qu''elle reconnaît comme réel). La réponse B est donc correcte. La réponse A est une demi-vérité : l''auteur reconnaît le phénomène mais pas comme une menace inquiétante. La réponse C adopte une position adjacente mais inverse à l''auteur (qui défend les salariés, pas l''entreprise). La réponse D présente un raccourci littéral : l''auteur ne dit pas que le terme vient des États-Unis pour le critiquer (c''est une simple mention factuelle, pas un argument).','true','2026-05-27 17:40:30.264599+02','2026-05-27 17:40:30.264599+02','ACTIVE',NULL,NULL,'ce_ton_auteur');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0020-0000-0000-000000000011','TCF','22222222-0000-0000-0000-000000000002',NULL,'33333333-0020-0000-0000-000000000003','B2','CE','Selon l''auteure, comment expliquer le comportement décrit par cette expression ?','L''auteure parle d''un « désengagement défensif » survenant « en réaction à des conditions perçues comme injustes : management vertical, salaires stagnants, demandes opérationnelles croissantes ». Elle ajoute que ces salariés expriment « non pas un refus du travail, mais le refus d''un déséquilibre durable entre ce qui est donné et ce qui est reconnu ». La réponse B reformule fidèlement cette idée. La réponse A est une demi-vérité : la rémunération est citée, mais pas seule. La réponse C inverse le propos : l''auteure ne juge pas les salariés paresseux. La réponse D adopte une position adjacente mais trop générale : l''auteure ne parle pas d''un changement de génération, mais d''un déséquilibre durable.','true','2026-05-27 17:40:30.264599+02','2026-05-27 17:40:30.264599+02','ACTIVE',NULL,NULL,'ce_reformulation');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0020-0000-0000-000000000012','TCF','22222222-0000-0000-0000-000000000002',NULL,'33333333-0020-0000-0000-000000000004','B2','CE','Quelle est la thèse principale de cette tribune ?','L''auteure conclut : « la vraie question n''est donc pas l''IA va-t-elle remplacer les artistes, mais que valait notre définition de l''art si une machine peut désormais en produire les apparences ». Elle déplace le débat : ce n''est pas l''IA le sujet, mais notre façon de définir l''art. La réponse C reformule cette inversion. La réponse A est une position adjacente mais trop tranchée : l''auteure ne dit pas que l''IA est inoffensive, elle dit qu''elle pose une autre question. La réponse B est une demi-vérité : l''auteure cite bien la « purification » mais comme conséquence, pas comme thèse principale. La réponse D adopte une position contraire : l''auteure refuse explicitement de présenter l''IA comme une menace existentielle.','true','2026-05-27 17:40:30.264599+02','2026-05-27 17:40:30.264599+02','ACTIVE',NULL,NULL,'ce_idee_principale');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0020-0000-0000-000000000013','TCF','22222222-0000-0000-0000-000000000002',NULL,'33333333-0020-0000-0000-000000000004','B2','CE','Que reste-t-il à l''art selon l''auteure, une fois l''IA généralisée ?','L''auteure écrit : « Avec l''IA, la prouesse technique se banalise. Reste l''intention : le pourquoi, le sens, le regard », et plus loin « l''intuition d''un vécu, la décision de montrer ceci plutôt que cela, la singularité d''un parcours ». La réponse B reformule cet ensemble : intention, choix, singularité — ce qu''aucune machine ne peut reproduire. La réponse A reprend littéralement « le savoir-faire technique » alors que l''auteure dit exactement l''inverse : c''est ce qui se banalise et n''est plus distinctif. La réponse C est une demi-vérité : la créativité n''est pas refusée à l''IA, mais redéfinie. La réponse D contredit l''auteure qui ne lie pas la valeur à la rareté du résultat mais à la singularité de la démarche.','true','2026-05-27 17:40:30.264599+02','2026-05-27 17:40:30.264599+02','ACTIVE',NULL,NULL,'ce_inference_intention');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0020-0000-0000-000000000014','TCF','22222222-0000-0000-0000-000000000002',NULL,'33333333-0020-0000-0000-000000000005','B2','CE','Combien madame Leroux devra-t-elle payer chaque mois à compter du 1er avril ?','Il faut additionner deux éléments distincts présentés dans la lettre : le nouveau loyer hors charges après révision IRL (848,70 €) et le complément temporaire pour travaux (15 € par mois pendant 12 mois). Total mensuel : 848,70 + 15 = 863,70 €. La réponse A donne le loyer après révision IRL mais oublie le complément travaux (demi-vérité). La réponse C ajoute le complément à l''ancien loyer, ce qui ignore la révision IRL (reformulation faussée). La réponse D présente la variation seule (28,70 €), qui est la hausse, pas le loyer.','true','2026-05-27 17:40:30.264599+02','2026-05-27 17:40:30.264599+02','ACTIVE',NULL,NULL,'ce_detail_specifique');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0020-0000-0000-000000000015','TCF','22222222-0000-0000-0000-000000000002',NULL,'33333333-0020-0000-0000-000000000005','B2','CE','Que peut faire madame Leroux si elle conteste cette révision ?','L''encadré « VOIE DE CONTESTATION » précise qu''elle peut « saisir la commission départementale de conciliation » dans un délai de « deux mois ». Le recours est donc administratif et limité dans le temps. La réponse A est correcte. La réponse B adopte une position adjacente plausible mais erronée : aucune mention d''un tribunal n''est faite, et le texte oriente vers une commission, pas un juge. La réponse C est trompeuse : « refuser de payer » n''est jamais évoqué comme voie légale (et c''est juridiquement risqué). La réponse D inverse la situation : le complément travaux n''est pas une renégociation à demander, c''est une décision unilatérale du bailleur encadrée par la loi.','true','2026-05-27 17:40:30.264599+02','2026-05-27 17:40:30.264599+02','ACTIVE',NULL,NULL,'ce_inference_intention');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0020-0000-0000-000000000016','TCF','22222222-0000-0000-0000-000000000002',NULL,'33333333-0020-0000-0000-000000000006','B2','CE','Quelle conclusion centrale ce rapport met-il en évidence ?','Le rapport titre « Un décalage croissant entre les actions menées et les attentes réelles des collaborateurs ». Il développe que les dispositifs visibles (baby-foot, événements, séminaires « bonheur ») sont jugés inutiles par 73 % des salariés, et que ces derniers attendent en priorité une revalorisation salariale, le respect du temps de vie personnelle et une reconnaissance managériale. La réponse C reformule cette thèse. La réponse A est une demi-vérité : la critique des dispositifs visibles existe, mais le rapport ne dit pas qu''ils sont nuisibles, juste qu''ils manquent leur cible. La réponse B est une position adjacente mais trop tranchée : le rapport recommande de réinvestir, pas de supprimer toute politique. La réponse D inverse le message : le rapport critique l''inadéquation des entreprises, pas le désintérêt des salariés.','true','2026-05-27 17:40:30.264599+02','2026-05-27 17:40:30.264599+02','ACTIVE',NULL,NULL,'ce_idee_principale');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0020-0000-0000-000000000017','TCF','22222222-0000-0000-0000-000000000002',NULL,'33333333-0020-0000-0000-000000000006','B2','CE','Que recherchent prioritairement les salariés interrogés ?','Le rapport identifie « trois axes fondamentaux : la rémunération, le respect du temps de vie personnelle, et la reconnaissance par le management direct du travail accompli ». La réponse B reformule cet ensemble. La réponse A est une demi-vérité : la rémunération est citée mais isolée des deux autres axes. La réponse C est une position adjacente mais erronée : le rapport critique les dispositifs cosmétiques, pas les conditions de travail au sens des équipements. La réponse D adopte une formulation trop large : « plus de flexibilité » n''est pas mentionné comme tel dans les chiffres clés.','true','2026-05-27 17:40:30.264599+02','2026-05-27 17:40:30.264599+02','ACTIVE',NULL,NULL,'ce_reformulation');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0020-0000-0000-000000000018','TCF','22222222-0000-0000-0000-000000000002',NULL,'33333333-0020-0000-0000-000000000007','B2','CE','Quelle attitude l''auteure adopte-t-elle face au slow tourisme ?','L''auteure reconnaît un « engagement écologique sérieux » sur le papier mais pointe que dans les faits, le slow tourisme « s''ajoute à des voyages longue distance, sans s''y substituer ». Elle conclut : « Faut-il pour autant disqualifier la démarche ? Certainement pas. Mais il faut sortir d''une lecture cosmétique ». Sa position est donc critique mais constructive : elle ne rejette pas, elle exige de la cohérence. La réponse B reformule cette nuance. La réponse A est une position adjacente trop tranchée (l''auteure ne disqualifie pas la démarche). La réponse C inverse le propos (l''auteure n''est pas enthousiaste). La réponse D est une demi-vérité : l''auteure critique l''usage cosmétique mais ne le réduit pas à du « pur marketing ».','true','2026-05-27 17:40:30.264599+02','2026-05-27 17:40:30.264599+02','ACTIVE',NULL,NULL,'ce_ton_auteur');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0020-0000-0000-000000000019','TCF','22222222-0000-0000-0000-000000000002',NULL,'33333333-0020-0000-0000-000000000007','B2','CE','Quel comportement de voyageur l''auteure critique-t-elle implicitement ?','L''auteure écrit : « le slow tourisme s''ajoute à des voyages longue distance, sans s''y substituer. On part en train à 200 km de chez soi pour un week-end responsable, puis on prend l''avion six mois plus tard pour les vraies vacances ». Le comportement critiqué est donc celui d''un cumul plutôt que d''un arbitrage. La réponse C reformule cette logique. La réponse A est une demi-vérité : le voyageur paresseux n''est pas évoqué. La réponse B confond le contenu (le voyage) et le critère (l''écologie). La réponse D propose une position adjacente mais inverse : l''auteure ne critique pas l''absence de voyage, mais l''ajout d''un voyage « propre » à des voyages polluants.','true','2026-05-27 17:40:30.264599+02','2026-05-27 17:40:30.264599+02','ACTIVE',NULL,NULL,'ce_inference_intention');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0020-0000-0000-000000000020','TCF','22222222-0000-0000-0000-000000000002',NULL,'33333333-0020-0000-0000-000000000008','B2','CE','Quel profil peut postuler à cette formation ?','La page exige quatre conditions cumulatives : Bac+3 minimum, « au moins 5 ans d''expérience professionnelle dont 2 en encadrement », sélection sur dossier ET entretien individuel obligatoire. La réponse B respecte tous ces critères (Bac+3 OK, 6 ans dont 3 d''encadrement OK). La réponse A échoue sur l''encadrement (1 an seulement, alors que 2 sont exigés). La réponse C échoue sur le diplôme (Bac+2 ne suffit pas, même avec une longue expérience — la page mentionne la VAE comme équivalence possible mais elle n''est pas demandée ici). La réponse D échoue sur l''expérience d''encadrement (4 ans d''expérience totale, dont aucune en encadrement déclarée).','true','2026-05-27 17:40:30.264599+02','2026-05-27 17:40:30.264599+02','ACTIVE',NULL,NULL,'ce_reperage_explicite');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0020-0000-0000-000000000021','TCF','22222222-0000-0000-0000-000000000002',NULL,'33333333-0020-0000-0000-000000000008','B2','CE','Que peut-on déduire de la mention « éligible CPF + financement employeur possible » ?','La mention indique deux voies cumulables ou alternatives : utiliser le compte personnel de formation (CPF) du candidat, et/ou demander un financement à son employeur. Aucune des deux n''est obligatoire, et elles peuvent se combiner. La réponse B reformule cette flexibilité. La réponse A est une position adjacente trop restrictive : aucune des deux n''est obligatoire. La réponse C inverse la logique : la mention rend possible plusieurs solutions, sans imposer le financement personnel. La réponse D est une demi-vérité : l''employeur peut financer, mais ce n''est pas mentionné comme obligatoire pour autant — c''est une « possibilité ».','true','2026-05-27 17:40:30.264599+02','2026-05-27 17:40:30.264599+02','ACTIVE',NULL,NULL,'ce_detail_specifique');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0020-0000-0000-000000000030','TCF','22222222-0000-0000-0000-000000000002','44444444-0020-0000-0000-000000000002',NULL,'B2','CE','Quelle position l''auteur défend-il face à l''évolution du rapport au travail ?','L''auteur écrit : « ce n''est pas le travail qui est rejeté, mais l''idée qu''il doive sacrifier le reste » et appelle les organisations à « entendre ce déplacement, sans se contenter d''ajuster à la marge ». Sa position est donc d''accompagner le changement plutôt que de le combattre. La réponse B reformule cette posture. La réponse A est une position adjacente mais inverse : l''auteur ne juge pas alarmiste, au contraire. La réponse C est une demi-vérité : l''auteur cite cette inquiétude mais s''en distancie ensuite. La réponse D contredit l''auteur qui ne dit pas que le travail garde sa place sacrée — il dit l''inverse, que cette centralité s''effrite.','true','2026-05-27 17:40:30.264599+02','2026-05-27 17:40:30.264599+02','ACTIVE',NULL,NULL,'ce_ton_auteur');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0020-0000-0000-000000000031','TCF','22222222-0000-0000-0000-000000000002','44444444-0020-0000-0000-000000000002',NULL,'B2','CE','Selon l''auteur, qu''est-ce qui a changé dans le rapport au travail ?','L''auteur écrit que les actifs « refusent qu''il occupe toute la place » et résume : « Conciliation, sens, équilibre : les mots ont changé, et avec eux les attentes ». Plus loin : « ce n''est pas le travail qui est rejeté, mais l''idée qu''il doive sacrifier le reste ». La réponse C reformule exactement ce déplacement. La réponse A est une demi-vérité : la baisse d''importance est nuancée par l''auteur (« la majorité continuent de juger le travail important »). La réponse B est une position adjacente erronée : c''est l''attente patronale qui est jugée excessive, pas l''attente salariale. La réponse D adopte une formulation trop tranchée : l''auteur ne parle pas de génération en particulier, mais d''une évolution générale.','true','2026-05-27 17:40:30.264599+02','2026-05-27 17:40:30.264599+02','ACTIVE',NULL,NULL,'ce_reformulation');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0020-0000-0000-000000000032','TCF','22222222-0000-0000-0000-000000000002','44444444-0020-0000-0000-000000000003',NULL,'B2','CE','Quelle est l''idée centrale développée dans ce texte ?','L''auteur décrit la limitation de la voiture en ville, mais insiste sur « le risque d''une fracture territoriale » entre centre et périphérie, et conclut : « réussir la transition, ce n''est pas seulement adopter de bonnes mesures : c''est aussi garantir qu''elles ne creusent pas, sous prétexte d''écologie, de nouvelles formes d''injustice sociale ». Il défend donc une transition qui doit être socialement juste. La réponse B reformule cette thèse. La réponse A est une position adjacente trop tranchée : l''auteur ne critique pas les mesures, il appelle à les compléter. La réponse C est une demi-vérité : il décrit le succès en centre-ville mais sa thèse principale dépasse ce constat. La réponse D inverse le propos : l''auteur ne défend pas la voiture, il défend l''équité de la transition.','true','2026-05-27 17:40:30.264599+02','2026-05-27 17:40:30.264599+02','ACTIVE',NULL,NULL,'ce_idee_principale');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0020-0000-0000-000000000033','TCF','22222222-0000-0000-0000-000000000002','44444444-0020-0000-0000-000000000003',NULL,'B2','CE','Pourquoi les habitants des couronnes périurbaines vivent-ils mal ces politiques ?','Le texte précise que ces habitants sont « mal desservis par les transports collectifs » et que les nouvelles politiques se traduisent pour eux par « trajets allongés, stationnement plus rare, factures de carburant en hausse ». Leur situation est donc subie : ils dépendent de la voiture par défaut d''alternatives. La réponse C reformule cette logique. La réponse A est une position adjacente mais réductrice : ce n''est pas une question de principe écologique, c''est une contrainte pratique. La réponse B inverse la logique : ils ne sont pas hostiles à l''écologie, ils subissent un effet collatéral. La réponse D est une demi-vérité : les factures de carburant augmentent, mais ce n''est pas la cause unique.','true','2026-05-27 17:40:30.264599+02','2026-05-27 17:40:30.264599+02','ACTIVE',NULL,NULL,'ce_inference_intention');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0020-0000-0000-000000000034','TCF','22222222-0000-0000-0000-000000000002','44444444-0020-0000-0000-000000000004',NULL,'B2','CE','Comment l''auteur juge-t-il le journalisme d''information continue ?','L''auteur écrit : « Le constat n''invalide pas le journalisme d''actualité, encore moins le rôle essentiel des rédactions. Il interroge en revanche une mécanique éditoriale qui privilégie souvent la rapidité sur la mise en perspective ». Il distingue donc le métier (qu''il défend) de la mécanique éditoriale dominante (qu''il critique). La réponse C reformule cette distinction. La réponse A inverse partiellement le propos : l''auteur ne rejette pas le journalisme, il critique son fonctionnement actuel. La réponse B est une position adjacente erronée : l''auteur valorise le journalisme, pas la « lassitude informationnelle ». La réponse D est une demi-vérité : il évoque des tentatives positives mais ne les juge pas suffisantes.','true','2026-05-27 17:40:30.264599+02','2026-05-27 17:40:30.264599+02','ACTIVE',NULL,NULL,'ce_ton_auteur');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0020-0000-0000-000000000035','TCF','22222222-0000-0000-0000-000000000002','44444444-0020-0000-0000-000000000004',NULL,'B2','CE','Comment l''auteur explique-t-il la « lassitude informationnelle » ?','L''auteur écrit que cette lassitude vient de l''exposition « en continu à des nouvelles souvent anxiogènes et décontextualisées » et que la mécanique éditoriale « privilégie souvent la rapidité sur la mise en perspective ». La cause est donc structurelle : le format même de l''information continue, pas son contenu en soi. La réponse B reformule cette analyse. La réponse A est une demi-vérité : l''auteur ne dit pas que les lecteurs sont devenus paresseux. La réponse C inverse la causalité : l''auteur ne dit pas que les journalistes manquent de talent, mais que le format les contraint. La réponse D est une position adjacente erronée : l''auteur ne pointe pas le manque de fiabilité, mais l''absence de mise en perspective.','true','2026-05-27 17:40:30.264599+02','2026-05-27 17:40:30.264599+02','ACTIVE',NULL,NULL,'ce_inference_intention');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0020-0000-0000-000000000036','TCF','22222222-0000-0000-0000-000000000002','44444444-0020-0000-0000-000000000005',NULL,'B2','CE','Quel paradoxe le texte met-il en évidence concernant la seconde main ?','L''auteur écrit : « La seconde main, conçue à l''origine comme une alternative à la surproduction, en devient parfois un prolongement déguisé », car « certains consommateurs achètent désormais plus, parce qu''ils achètent moins cher et avec moins de culpabilité ». La réponse C reformule ce paradoxe. La réponse A est une position adjacente erronée : l''auteur ne nie pas l''intérêt écologique. La réponse B est une demi-vérité : le marché s''est industrialisé, mais ce n''est pas le paradoxe central. La réponse D est une formulation trop tranchée : l''auteur ne dit pas que la seconde main est néfaste, mais qu''elle peut être déviée de son objectif.','true','2026-05-27 17:40:30.264599+02','2026-05-27 17:40:30.264599+02','ACTIVE',NULL,NULL,'ce_idee_principale');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0020-0000-0000-000000000037','TCF','22222222-0000-0000-0000-000000000002','44444444-0020-0000-0000-000000000005',NULL,'B2','CE','Quel comportement adoptent certains consommateurs face à l''offre d''occasion ?','L''auteur précise : « Certains consommateurs achètent désormais plus, parce qu''ils achètent moins cher et avec moins de culpabilité ». L''effet pervers tient à la conjonction de deux ressorts : prix bas + bonne conscience. La réponse B reformule cette double cause. La réponse A est une demi-vérité : le prix bas est cité, mais isolément. La réponse C est une position adjacente erronée : l''auteur ne dit pas qu''ils achètent autant qu''avant, il dit qu''ils achètent plus. La réponse D inverse le propos : il n''est pas question d''un retour au neuf, mais d''une consommation accrue de seconde main.','true','2026-05-27 17:40:30.264599+02','2026-05-27 17:40:30.264599+02','ACTIVE',NULL,NULL,'ce_detail_specifique');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0020-0000-0000-000000000038','TCF','22222222-0000-0000-0000-000000000002','44444444-0020-0000-0000-000000000006',NULL,'B2','CE','Quelles limites du « sport sur ordonnance » l''auteur identifie-t-il ?','L''auteur évoque trois limites cumulées : la dépendance « à la motivation du patient et à son accès géographique à des structures adaptées », « le reste à charge » dissuasif pour les ménages modestes, et le besoin d''un « accompagnement humain » sans lequel l''adhésion s''effrite. La réponse B reformule cet ensemble. La réponse A est une position adjacente erronée : l''auteur ne remet pas en cause l''efficacité scientifique du dispositif (« les bénéfices ne font plus débat »). La réponse C est une demi-vérité : l''accès géographique est cité, mais isolé des autres limites. La réponse D contredit l''auteur, qui souligne au contraire que les professionnels apprécient le dispositif.','true','2026-05-27 17:40:30.264599+02','2026-05-27 17:40:30.264599+02','ACTIVE',NULL,NULL,'ce_reformulation');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0020-0000-0000-000000000039','TCF','22222222-0000-0000-0000-000000000002','44444444-0020-0000-0000-000000000006',NULL,'B2','CE','Quelle position l''auteur adopte-t-il face au dispositif ?','L''auteur écrit : « Promouvoir le sport-santé comme outil thérapeutique est donc une excellente intention ; le réussir suppose de penser, en amont, les conditions concrètes de son déploiement à grande échelle. Sinon, ce qui devait être un progrès collectif risque de ne profiter qu''aux mieux dotés ». Sa position est favorable au principe, mais exigeante sur les conditions. La réponse D reformule cette nuance. La réponse A est une demi-vérité : la critique des inégalités existe, mais l''auteur ne juge pas le dispositif inéquitable « par nature ». La réponse B est une position adjacente trop enthousiaste. La réponse C contredit l''auteur, qui défend le dispositif sur le principe.','true','2026-05-27 17:40:30.264599+02','2026-05-27 17:40:30.264599+02','ACTIVE',NULL,NULL,'ce_ton_auteur');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0020-0000-0000-000000000040','TCF','22222222-0000-0000-0000-000000000002','44444444-0020-0000-0000-000000000007',NULL,'B2','CE','Quel message principal le texte cherche-t-il à transmettre ?','L''auteur conclut : « Surveiller à distance, c''est aussi reconnaître implicitement qu''on doute. Or la confiance, longuement érigée comme un pilier des organisations modernes, supporte mal d''être ainsi remise en cause. À vouloir tout mesurer, on risque surtout de mesurer la perte d''engagement ». Le message est donc que la surveillance fait peser une menace sur la relation de confiance et l''engagement. La réponse C reformule cette idée. La réponse A est une demi-vérité : la dimension juridique est évoquée mais n''est pas le message central. La réponse B est une position adjacente trop tranchée : l''auteur ne défend pas le télétravail en soi. La réponse D contredit l''auteur qui critique la généralisation de ces outils.','true','2026-05-27 17:40:30.264599+02','2026-05-27 17:40:30.264599+02','ACTIVE',NULL,NULL,'ce_idee_principale');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0020-0000-0000-000000000041','TCF','22222222-0000-0000-0000-000000000002','44444444-0020-0000-0000-000000000007',NULL,'B2','CE','Que veut dire l''auteur en concluant « à vouloir tout mesurer, on risque surtout de mesurer la perte d''engagement » ?','L''auteur joue sur le double sens du verbe « mesurer » : les outils de surveillance prétendent mesurer la productivité, mais en réalité, ils provoquent un désengagement qui apparaît alors dans les indicateurs. La conséquence visée se retourne contre celui qui la met en place. La réponse C reformule ce retournement. La réponse A confond mesure (l''outil) et productivité (l''effet attendu) : l''auteur ne dit pas que la mesure améliore la productivité. La réponse B est une demi-vérité : l''outil détecte effectivement quelque chose, mais c''est l''effet pervers de son existence. La réponse D est une position adjacente trop simpliste : l''auteur ne dit pas que la surveillance est inutile, mais qu''elle est contre-productive.','true','2026-05-27 17:40:30.264599+02','2026-05-27 17:40:30.264599+02','ACTIVE',NULL,NULL,'ce_reformulation');
